// Manages a pointer to a CDC whether generated by window or the app.


#include "pch.h"
#include "CDCex.h"

CDCex displayDC;
CDCex printerDC;


CDCex::~CDCex() {NewAlloc(CDC);   if (attached && dc) FreeNode(dc);   dc = 0;   attached = false;}


bool CDCex::attach(HDC hdc) {
NewAlloc(CDC);

  if (!hdc) return false;

  if (!dc) {dc = AllocNode;   if (!dc) return false;}

  dc->m_bPrinting = TRUE;

  if (!dc->Attach(hdc)) {String s;   getError(::GetLastError(), s);   messageBox(s);}

  attached = true;   return true;
  }



// Using the actual dimension in pixels and milimeters find the corresponding inches in pixels

int CDCex::xActualPixels(double inches) {
double widthPxls = dc->GetDeviceCaps(HORZRES);
double widthMM   = dc->GetDeviceCaps(HORZSIZE);

  return int((25.4 * inches * widthPxls / widthMM) + 0.5);
  }


int CDCex::yActualPixels(double inches) {
double heightPxls = dc->GetDeviceCaps(VERTRES);
double heightMM   = dc->GetDeviceCaps(VERTSIZE);

  return int((25.4 * inches * heightPxls / heightMM) + 0.5);
  }




